"kind": "propose",
"summary": "The API container is throttled at its CPU limit (0.5), with 64% throttling ratio and 0.495 CPU usage, causing readiness probe failures. Increasing the CPU limit to 750m should resolve this.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "CPU usage is near the limit (0.495/0.5) and throttling is high (64%), causing readiness probe timeouts.",
    "supporting": ["ev-container_cpu", "ev-target_events"],
    "contradicting": [],
    "missing": ["ev-revision_health"],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "api": {
        "limits": {
          "cpu": "750m"
        }
      }
    }
  },
  "expected_effect": "Raises the CPU limit of the API container to 750m, which should reduce throttling and allow readiness probes to pass.",
  "rationale": "The container is consistently hitting its CPU limit (0.495/0.5) and being throttled 64% of the time, causing readiness probe timeouts. Increasing the limit to 750m (1.5x current) should clear the throttling without affecting memory or other resources. The previous version (revision 1) lacks throttling metrics, so we assume the new version's higher usage is the cause.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-target_events", "ev-revision_health"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit"]
}
}
